package com.game_manager.gm.workflow.dto; import com.game_manager.gm.workflow.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public record WorkflowSummaryResponse(UUID id,String definitionKey,String title,BigDecimal amount,WorkflowStatus status,String currentStep,Instant dueAt,boolean escalated,long version,List<String> allowedActions){public static WorkflowSummaryResponse from(WorkflowInstance i,List<String>a){return new WorkflowSummaryResponse(i.getId(),i.getDefinitionVersion().getDefinition().getDefinitionKey(),i.getTitle(),i.getAmount(),i.getStatus(),i.getCurrentStepKey(),i.getDueAt(),i.isEscalated(),i.getVersion(),a);}}
